import{_ as t,o as s,c as a,ai as o}from"./chunks/framework.CUYGB37K.js";const h=JSON.parse('{"title":"Product Completeness","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/products/completeness.md","filePath":"1.0/products/completeness.md","lastUpdated":1779083873000}'),i={name:"1.0/products/completeness.md"};function n(r,e,l,c,u,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="product-completeness" tabindex="-1">Product Completeness <a class="header-anchor" href="#product-completeness" aria-label="Permalink to &quot;Product Completeness&quot;">​</a></h1><p>Product Completeness provides a visual score and detailed evaluation of product data quality based on your completeness settings. It helps you identify which products are ready for publish and which ones need more information.</p><h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><p>UnoPim evaluates product completeness based on the attributes assigned to a product&#39;s family. You can configure which attributes are &quot;required&quot; for a product to be considered complete.</p><h3 id="completeness-score" tabindex="-1">Completeness Score <a class="header-anchor" href="#completeness-score" aria-label="Permalink to &quot;Completeness Score&quot;">​</a></h3><p>The score is calculated as a percentage: <code>(Number of filled required attributes) / (Total number of required attributes) * 100</code></p><h2 id="completeness-settings" tabindex="-1">Completeness Settings <a class="header-anchor" href="#completeness-settings" aria-label="Permalink to &quot;Completeness Settings&quot;">​</a></h2><p>You can define completeness rules in the attribute management section.</p><ol><li>Navigate to <strong>catalog &gt;&gt; Attributes families</strong> Select an attribute family.</li><li>Click on the <strong>Completeness</strong> tab.</li><li>Mark attributes as <strong>Required in Channels</strong> for completeness evaluation and save.</li></ol><h2 id="calculation-queue" tabindex="-1">Calculation Queue <a class="header-anchor" href="#calculation-queue" aria-label="Permalink to &quot;Calculation Queue&quot;">​</a></h2><p>Completeness calculation jobs are processed via the system queue to ensure real-time updates without affecting performance.</p><p>To start the queue worker, use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue:work</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --queue=system,default</span></span></code></pre></div><h2 id="viewing-completeness" tabindex="-1">Viewing Completeness <a class="header-anchor" href="#viewing-completeness" aria-label="Permalink to &quot;Viewing Completeness&quot;">​</a></h2><p>The completeness score is visible in:</p><ul><li><strong>Product Datagrid</strong>: As a percentage column.</li><li><strong>Product Edit Page</strong>: Detailed breakdown of missing attributes.</li></ul>',16)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
